def expected_score(n, k):
    from functools import lru_cache

    @lru_cache(None)
    def E(n, k):
        if k == 1:
            return (1 + n) / 2
        else:
            return (E(n, k-1) + sum(max(i, E(n, k-1)) for i in range(1, n+1))) / n

    return E(n, k)

